export function firstOr<T>(items: readonly T[], fallback: T): T {
  for (const item of items) {
    return item;
  }
  return fallback;
}

export function atOr<T>(items: readonly T[], index: number, fallback: T): T {
  const resolved = index < 0 ? items.length + index : index;
  if (resolved < 0 || resolved >= items.length) {
    return fallback;
  }
  return items[resolved];
}

// v3tb01_inferable_generics / ex2 - reference solution (author only).

export function pluck<T, K extends keyof T>(items: readonly T[], key: K): T[K][] {
  return items.map((item) => item[key]);
}

export function pluckUnique<T, K extends keyof T>(
  items: readonly T[],
  key: K,
): T[K][] {
  const seen = new Set<T[K]>();
  const result: T[K][] = [];
  for (const item of items) {
    const value = item[key];
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}

// v3tb01_inferable_generics / ex3 - reference solution (author only).

export function groupBy<T, K extends PropertyKey>(
  items: readonly T[],
  keyOf: (item: T, index: number) => K,
): Record<K, T[]> {
  const groups: Partial<Record<K, T[]>> = Object.create(null) as Partial<
    Record<K, T[]>
  >;
  items.forEach((item, index) => {
    const key = keyOf(item, index);
    const bucket = groups[key];
    if (bucket === undefined) {
      groups[key] = [item];
    } else {
      bucket.push(item);
    }
  });
  return groups as Record<K, T[]>;
}

