export interface RouteTable<T extends readonly string[]> {
  readonly paths: T;
  readonly index: Readonly<Record<T[number], number>>;
  includes(path: string): path is T[number];
}

export function defineRoutes<const T extends readonly string[]>(
  paths: T,
): RouteTable<T> {
  const index = {} as Record<T[number], number>;
  const known = new Set<string>(paths);

  paths.forEach((path, position) => {
    const key = path as T[number];
    if (!(path in index)) {
      index[key] = position;
    }
  });

  return {
    paths,
    index,
    includes(path: string): path is T[number] {
      return known.has(path);
    },
  };
}

// v3tb01_inferable_generics / ex5 - reference solution (author only).

export interface Chooser<T> {
  readonly options: readonly T[];
  readonly fallback: T;
  choose(value: unknown): T;
}

export function chooser<T>(
  options: readonly T[],
  fallback: NoInfer<T>,
): Chooser<T> {
  const allowed = new Set<unknown>(options);
  return {
    options,
    fallback,
    choose(value: unknown): T {
      // The cast is paid for by the membership test: anything in `allowed`
      // came from `options`, whose element type is T.
      return allowed.has(value) ? (value as T) : fallback;
    },
  };
}

