export interface User {
  id: number;
  name: string;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function decodeUser(value: unknown): User {
  if (!isRecord(value)) {
    throw new TypeError("expected an object");
  }
  const { id, name } = value;
  if (typeof id !== "number" || !Number.isInteger(id)) {
    throw new TypeError("id must be an integer");
  }
  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("name must be a non-empty string");
  }
  return { id, name };
}

export function parseJson<T>(text: string, decode: (value: unknown) => T): T {
  const raw: unknown = JSON.parse(text);
  return decode(raw);
}

// v3tb01_inferable_generics / ex7 - reference solution (author only).

export function withRetry<A extends readonly unknown[], R>(
  fn: (...args: A) => Promise<R>,
  attempts: number,
  onRetry?: (error: unknown, attempt: number) => void,
): (...args: A) => Promise<R> {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError(`attempts must be a positive integer, got ${attempts}`);
  }

  return async (...args: A): Promise<R> => {
    let lastError: unknown;
    for (let attempt = 1; attempt <= attempts; attempt += 1) {
      try {
        return await fn(...args);
      } catch (error) {
        lastError = error;
        if (attempt < attempts) {
          onRetry?.(error, attempt);
        }
      }
    }
    throw lastError;
  };
}

