export function pipe<A, B>(value: A, ab: (a: A) => B): B;
export function pipe<A, B, C>(value: A, ab: (a: A) => B, bc: (b: B) => C): C;
export function pipe<A, B, C, D>(
  value: A,
  ab: (a: A) => B,
  bc: (b: B) => C,
  cd: (c: C) => D,
): D;
export function pipe<A, B, C, D, E>(
  value: A,
  ab: (a: A) => B,
  bc: (b: B) => C,
  cd: (c: C) => D,
  de: (d: D) => E,
): E;
export function pipe(
  value: unknown,
  ...fns: ReadonlyArray<(input: unknown) => unknown>
): unknown {
  return fns.reduce((accumulator, fn) => fn(accumulator), value);
}

export function flow<A extends readonly unknown[], B>(
  ab: (...args: A) => B,
): (...args: A) => B;
export function flow<A extends readonly unknown[], B, C>(
  ab: (...args: A) => B,
  bc: (b: B) => C,
): (...args: A) => C;
export function flow<A extends readonly unknown[], B, C, D>(
  ab: (...args: A) => B,
  bc: (b: B) => C,
  cd: (c: C) => D,
): (...args: A) => D;
export function flow<A extends readonly unknown[], B, C, D, E>(
  ab: (...args: A) => B,
  bc: (b: B) => C,
  cd: (c: C) => D,
  de: (d: D) => E,
): (...args: A) => E;
// The implementation signature is invisible to callers, so `any` here buys
// flexibility without leaking: every public entry point above is precise.
export function flow(
  first: (...args: any[]) => unknown,
  ...rest: ReadonlyArray<(input: any) => unknown>
): (...args: any[]) => unknown {
  return (...args: any[]): unknown =>
    rest.reduce((accumulator, fn) => fn(accumulator), first(...args));
}

