export interface Table<Row> {
  readonly rows: readonly Row[];
  where(predicate: (row: Row, index: number) => boolean): Table<Row>;
  select<const K extends readonly (keyof Row)[]>(
    keys: K,
  ): Array<Pick<Row, K[number]>>;
  sortBy<V>(project: (row: Row) => V, compare: (a: V, b: V) => number): Table<Row>;
  indexBy<K extends PropertyKey>(keyOf: (row: Row) => K): Map<K, Row>;
}

export function table<Row>(rows: readonly Row[]): Table<Row> {
  return {
    rows,

    where(predicate: (row: Row, index: number) => boolean): Table<Row> {
      return table(rows.filter((row, index) => predicate(row, index)));
    },

    select<const K extends readonly (keyof Row)[]>(
      keys: K,
    ): Array<Pick<Row, K[number]>> {
      return rows.map((row) => {
        const picked: Record<PropertyKey, unknown> = {};
        for (const key of keys) {
          picked[key as PropertyKey] = row[key];
        }
        // One assertion, at the boundary where the object is finished.
        return picked as unknown as Pick<Row, K[number]>;
      });
    },

    sortBy<V>(
      project: (row: Row) => V,
      compare: (a: V, b: V) => number,
    ): Table<Row> {
      const sorted = [...rows].sort((a, b) => compare(project(a), project(b)));
      return table(sorted);
    },

    indexBy<K extends PropertyKey>(keyOf: (row: Row) => K): Map<K, Row> {
      const index = new Map<K, Row>();
      for (const row of rows) {
        const key = keyOf(row);
        if (!index.has(key)) {
          index.set(key, row);
        }
      }
      return index;
    },
  };
}

