export interface Registry<N extends readonly string[]> {
  readonly names: N;
  readonly order: Readonly<Record<N[number], number>>;
  isKnown(value: string): value is N[number];
  sort<T>(items: readonly T[], keyOf: (item: T) => N[number]): T[];
}

export function createRegistry<const N extends readonly string[]>(
  names: N,
): Registry<N> {
  const order = {} as Record<N[number], number>;
  const known = new Set<string>();

  names.forEach((name, position) => {
    if (known.has(name)) {
      throw new RangeError(`duplicate registry name: ${name}`);
    }
    known.add(name);
    order[name as N[number]] = position;
  });

  return {
    names,
    order,

    isKnown(value: string): value is N[number] {
      return known.has(value);
    },

    sort<T>(items: readonly T[], keyOf: (item: T) => N[number]): T[] {
      return [...items].sort((a, b) => order[keyOf(a)] - order[keyOf(b)]);
    },
  };
}

