// v3tb02_parse_dont_validate / ex1 - reference solution (author only).

export type Decoder<T> = (value: unknown, path: string) => T;

export class DecodeError extends Error {
  readonly path: string;

  constructor(path: string, detail: string) {
    super(`${path}: ${detail}`);
    this.name = "DecodeError";
    this.path = path;
  }
}

export function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  return typeof value;
}

export const decodeString: Decoder<string> = (value, path) => {
  if (typeof value !== "string") {
    throw new DecodeError(path, `expected a string, got ${describe(value)}`);
  }
  return value;
};

export const decodeNumber: Decoder<number> = (value, path) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new DecodeError(path, `expected a finite number, got ${describe(value)}`);
  }
  return value;
};

export const decodeInteger: Decoder<number> = (value, path) => {
  const parsed = decodeNumber(value, path);
  if (!Number.isInteger(parsed)) {
    throw new DecodeError(path, `expected an integer, got ${parsed}`);
  }
  return parsed;
};

export const decodeBoolean: Decoder<boolean> = (value, path) => {
  if (typeof value !== "boolean") {
    throw new DecodeError(path, `expected a boolean, got ${describe(value)}`);
  }
  return value;
};

export function decodeLiteral<const L extends string | number | boolean>(
  literal: L,
): Decoder<L> {
  return (value, path) => {
    if (value !== literal) {
      throw new DecodeError(
        path,
        `expected ${JSON.stringify(literal)}, got ${JSON.stringify(value)}`,
      );
    }
    return literal;
  };
}

