const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function hasOwn<K extends string>(
  value: Record<string, unknown>,
  key: K,
): value is Record<string, unknown> & Record<K, unknown> {
  return Object.prototype.hasOwnProperty.call(value, key);
}

export function getPath(
  value: unknown,
  path: readonly (string | number)[],
): unknown {
  let current: unknown = value;

  for (const segment of path) {
    if (typeof segment === "number") {
      if (!Array.isArray(current)) return undefined;
      if (!Number.isInteger(segment) || segment < 0 || segment >= current.length) {
        return undefined;
      }
      current = current[segment];
      continue;
    }

    if (FORBIDDEN.has(segment)) return undefined;
    if (!isRecord(current)) return undefined;
    if (!hasOwn(current, segment)) return undefined;
    current = current[segment];
  }

  return current;
}

// v3tb02_parse_dont_validate / ex3 - reference solution (author only).

export interface Session {
  userId: string;
  expiresAt: number;
}

export function isSession(value: unknown): value is Session {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate["userId"] === "string" &&
    candidate["userId"].length > 0 &&
    typeof candidate["expiresAt"] === "number" &&
    Number.isInteger(candidate["expiresAt"])
  );
}

export function assertSession(value: unknown): asserts value is Session {
  if (!isSession(value)) {
    throw new TypeError("not a session");
  }
}

// An assertion reached through a const needs the type spelled out; without the
// annotation TypeScript refuses to narrow at the call site.
export const assertSessionRef: (value: unknown) => asserts value is Session =
  assertSession;

export function parseSession(value: unknown): Session {
  assertSession(value);
  return { userId: value.userId, expiresAt: value.expiresAt };
}

