export type Decoder<T> = (value: unknown, path: string) => T;
export type Infer<D> = D extends Decoder<infer T> ? T : never;

export class DecodeError extends Error {
  readonly path: string;
  readonly detail: string;
  constructor(path: string, detail: string) {
    super(`${path}: ${detail}`);
    this.name = "DecodeError";
    this.path = path;
    this.detail = detail;
  }
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  return typeof value;
}

export const decodeString: Decoder<string> = (value, path) => {
  if (typeof value !== "string") {
    throw new DecodeError(path, `expected a string, got ${describe(value)}`);
  }
  return value;
};

export const decodeNumber: Decoder<number> = (value, path) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new DecodeError(path, `expected a finite number, got ${describe(value)}`);
  }
  return value;
};

export function array<T>(inner: Decoder<T>): Decoder<T[]> {
  return (value, path) => {
    if (!Array.isArray(value)) {
      throw new DecodeError(path, `expected an array, got ${describe(value)}`);
    }
    const items: unknown[] = value;
    return items.map((item, index) => inner(item, `${path}[${index}]`));
  };
}

export function optional<T>(inner: Decoder<T>): Decoder<T | undefined> {
  return (value, path) => (value === undefined ? undefined : inner(value, path));
}

export function nullable<T>(inner: Decoder<T>): Decoder<T | null> {
  return (value, path) => (value === null ? null : inner(value, path));
}

export function union<D extends readonly Decoder<unknown>[]>(
  ...decoders: D
): Decoder<Infer<D[number]>> {
  return (value, path) => {
    const reasons: string[] = [];
    for (const decode of decoders) {
      try {
        return decode(value, path) as Infer<D[number]>;
      } catch (error) {
        reasons.push(
          error instanceof DecodeError ? error.detail : String(error),
        );
      }
    }
    throw new DecodeError(path, `no variant matched (${reasons.join("; ")})`);
  };
}

// v3tb02_parse_dont_validate / ex6 - reference solution (author only).

export type Decoder<T> = (value: unknown, path: string) => T;
export type Infer<D> = D extends Decoder<infer T> ? T : never;

export interface Issue {
  readonly path: string;
  readonly message: string;
}

export class DecodeError extends Error {
  readonly issues: readonly Issue[];
  constructor(issues: readonly Issue[]) {
    super(issues.map((issue) => `${issue.path}: ${issue.message}`).join("; "));
    this.name = "DecodeError";
    this.issues = issues;
  }
}

export type ParseResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly issues: readonly Issue[] };

function fail(path: string, message: string): never {
  throw new DecodeError([{ path, message }]);
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  return typeof value;
}

export const decodeString: Decoder<string> = (value, path) =>
  typeof value === "string"
    ? value
    : fail(path, `expected a string, got ${describe(value)}`);

export const decodeInteger: Decoder<number> = (value, path) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return fail(path, `expected a finite number, got ${describe(value)}`);
  }
  if (!Number.isInteger(value)) {
    return fail(path, `expected an integer, got ${value}`);
  }
  return value;
};

export function objectAll<S extends Record<string, Decoder<unknown>>>(
  shape: S,
): Decoder<{ [K in keyof S]: Infer<S[K]> }> {
  return (value, path) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return fail(path, `expected an object, got ${describe(value)}`);
    }
    const source = value as Record<string, unknown>;
    const result: Record<string, unknown> = {};
    const issues: Issue[] = [];

    for (const key of Object.keys(shape) as Array<keyof S & string>) {
      const decode = shape[key];
      try {
        result[key] = decode(source[key], `${path}.${key}`);
      } catch (error) {
        if (error instanceof DecodeError) {
          issues.push(...error.issues);
        } else {
          throw error;
        }
      }
    }

    if (issues.length > 0) {
      throw new DecodeError(issues);
    }
    return result as unknown as { [K in keyof S]: Infer<S[K]> };
  };
}

export function safeParse<T>(
  decoder: Decoder<T>,
  value: unknown,
): ParseResult<T> {
  try {
    return { ok: true, value: decoder(value, "$") };
  } catch (error) {
    if (error instanceof DecodeError) {
      return { ok: false, issues: error.issues };
    }
    throw error;
  }
}

// v3tb02_parse_dont_validate / ex7 - reference solution (author only).

declare const brandKey: unique symbol;

export type Brand<T, B extends string> = T & { readonly [brandKey]: B };

export type Email = Brand<string, "Email">;
export type UserId = Brand<string, "UserId">;
export type PositiveInt = Brand<number, "PositiveInt">;

const USER_ID = /^u_[0-9a-f]{8}$/;

function reject(path: string, expected: string, value: unknown): never {
  throw new TypeError(`${path}: expected ${expected}, got ${JSON.stringify(value)}`);
}

export function asEmail(value: unknown, path = "$"): Email {
  if (typeof value !== "string" || /\s/.test(value)) {
    reject(path, "an email", value);
  }
  const parts = value.split("@");
  if (parts.length !== 2 || parts[0].length === 0 || parts[1].length === 0) {
    reject(path, "an email", value);
  }
  // Justified by the checks above; there is no other way to attach a brand.
  return value as Email;
}

export function asUserId(value: unknown, path = "$"): UserId {
  if (typeof value !== "string" || !USER_ID.test(value)) {
    reject(path, "a user id", value);
  }
  return value as UserId;
}

export function asPositiveInt(value: unknown, path = "$"): PositiveInt {
  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    reject(path, "a positive integer", value);
  }
  return value as PositiveInt;
}

export function localPart(email: Email): string {
  // `email` is a string at runtime; the brand exists only for the checker,
  // which is also why `"x" as Email` still compiles. Brands stop accidents,
  // not assertions.
  return email.split("@")[0];
}

export function sendTo(email: Email, id: UserId): string {
  return `to ${email} for ${id}`;
}

