export type Prettify<T> = { [K in keyof T]: T[K] } & {};

export function object<S extends Record<string, Decoder<unknown>>>(
  shape: S,
): Decoder<Prettify<Shaped<S>>> {
  return (value, path) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new DecodeError(path, `expected an object, got ${describe(value)}`);
    }
    const source = value as Record<string, unknown>;
    const result: Record<string, unknown> = {};

    for (const key of Object.keys(shape) as Array<keyof S & string>) {
      const decode = shape[key];
      const decoded = decode(source[key], `${path}.${key}`);
      // Omit rather than assign undefined: the key should be absent.
      if (decoded !== undefined) {
        result[key] = decoded;
      }
    }

    return result as unknown as Prettify<Shaped<S>>;
  };
}

