export type Infer<D> = D extends Decoder<infer T> ? T : never;

export class DecodeError extends Error {
  readonly path: string;
  constructor(path: string, detail: string) {
    super(`${path}: ${detail}`);
    this.name = "DecodeError";
    this.path = path;
  }
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number" && !Number.isFinite(value)) return String(value);
  return typeof value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasOwn(value: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(value, key);
}

export const decodeString: Decoder<string> = (value, path) => {
  if (typeof value !== "string") {
    throw new DecodeError(path, `expected a string, got ${describe(value)}`);
  }
  return value;
};

export const decodeInteger: Decoder<number> = (value, path) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new DecodeError(path, `expected a finite number, got ${describe(value)}`);
  }
  if (!Number.isInteger(value)) {
    throw new DecodeError(path, `expected an integer, got ${value}`);
  }
  return value;
};

export function decodeLiteral<const L extends string>(literal: L): Decoder<L> {
  return (value, path) => {
    if (value !== literal) {
      throw new DecodeError(
        path,
        `expected ${JSON.stringify(literal)}, got ${JSON.stringify(value)}`,
      );
    }
    return literal;
  };
}

export function strictObject<S extends Record<string, Decoder<unknown>>>(
  shape: S,
): Decoder<{ [K in keyof S]: Infer<S[K]> }> {
  return (value, path) => {
    if (!isRecord(value)) {
      throw new DecodeError(path, `expected an object, got ${describe(value)}`);
    }
    const unexpected = Object.keys(value).find((key) => !hasOwn(shape, key));
    if (unexpected !== undefined) {
      throw new DecodeError(path, `unexpected key ${JSON.stringify(unexpected)}`);
    }

    const result: Record<string, unknown> = {};
    for (const key of Object.keys(shape) as Array<keyof S & string>) {
      const decode = shape[key];
      result[key] = decode(value[key], `${path}.${key}`);
    }
    return result as unknown as { [K in keyof S]: Infer<S[K]> };
  };
}

export function variant<K extends string, C extends Record<string, Decoder<unknown>>>(
  tagKey: K,
  cases: C,
): Decoder<Infer<C[keyof C]>> {
  const names = Object.keys(cases);
  return (value, path) => {
    if (!isRecord(value)) {
      throw new DecodeError(path, `expected an object, got ${describe(value)}`);
    }
    const tag = value[tagKey];
    if (typeof tag !== "string" || !hasOwn(cases, tag)) {
      throw new DecodeError(
        `${path}.${tagKey}`,
        `expected one of ${names.map((n) => JSON.stringify(n)).join(", ")}, ` +
          `got ${JSON.stringify(tag)}`,
      );
    }
    const decode = cases[tag as keyof C & string];
    return decode(value, path) as Infer<C[keyof C]>;
  };
}

export const decodeEvent = variant("kind", {
  click: strictObject({
    kind: decodeLiteral("click"),
    x: decodeInteger,
    y: decodeInteger,
  }),
  key: strictObject({ kind: decodeLiteral("key"), code: decodeString }),
  close: strictObject({ kind: decodeLiteral("close") }),
});

export type AppEvent = Infer<typeof decodeEvent>;

function assertNever(value: never): never {
  throw new Error(`unhandled variant: ${JSON.stringify(value)}`);
}

export function render(event: AppEvent): string {
  switch (event.kind) {
    case "click":
      return `click at ${event.x},${event.y}`;
    case "key":
      return `key ${event.code}`;
    case "close":
      return "close";
    default:
      return assertNever(event);
  }
}

