export type AppError =
  | { readonly code: "not_found"; readonly resource: string; readonly id: string }
  | { readonly code: "forbidden"; readonly action: string }
  | { readonly code: "timeout"; readonly ms: number }
  | { readonly code: "invalid"; readonly issues: readonly string[] };

export type ErrorHandlers<R> = {
  [K in AppError["code"]]: (error: Extract<AppError, { code: K }>) => R;
};

export function matchError<R>(error: AppError, handlers: ErrorHandlers<R>): R {
  // The runtime lookup pairs a tag with its handler; the type system cannot
  // follow that pairing, so this is the one assertion the pattern needs.
  const handler = handlers[error.code] as (error: AppError) => R;
  return handler(error);
}

export function describeError(error: AppError): string {
  return matchError(error, {
    not_found: (e) => `${e.resource} ${e.id} was not found`,
    forbidden: (e) => `not allowed to ${e.action}`,
    timeout: (e) => `timed out after ${e.ms}ms`,
    invalid: (e) => `invalid: ${e.issues.join(", ")}`,
  });
}

export function statusOf(error: AppError): number {
  return matchError(error, {
    not_found: () => 404,
    forbidden: () => 403,
    timeout: () => 504,
    invalid: () => 422,
  });
}

