export interface Chain<T, E> {
  map<U>(fn: (value: T) => U): Chain<U, E>;
  mapErr<F>(fn: (error: E) => F): Chain<T, F>;
  andThen<U, F>(fn: (value: T) => Result<U, F>): Chain<U, E | F>;
  match<R>(handlers: { ok: (value: T) => R; err: (error: E) => R }): R;
  done(): Result<T, E>;
}

export function chain<T, E>(result: Result<T, E>): Chain<T, E> {
  return {
    map<U>(fn: (value: T) => U): Chain<U, E> {
      return chain<U, E>(
        result.ok ? { ok: true, value: fn(result.value) } : result,
      );
    },
    mapErr<F>(fn: (error: E) => F): Chain<T, F> {
      return chain<T, F>(
        result.ok ? result : { ok: false, error: fn(result.error) },
      );
    },
    andThen<U, F>(fn: (value: T) => Result<U, F>): Chain<U, E | F> {
      return chain<U, E | F>(result.ok ? fn(result.value) : result);
    },
    match<R>(handlers: { ok: (value: T) => R; err: (error: E) => R }): R {
      return result.ok ? handlers.ok(result.value) : handlers.err(result.error);
    },
    done(): Result<T, E> {
      return result;
    },
  };
}

export function parseAmount(
  text: string,
): Result<number, { code: "not_a_number"; text: string }> {
  const trimmed = text.trim();
  const parsed = Number(trimmed);
  if (trimmed.length === 0 || !Number.isFinite(parsed)) {
    return { ok: false, error: { code: "not_a_number", text } };
  }
  return { ok: true, value: parsed };
}

export function checkRange(
  amount: number,
): Result<number, { code: "out_of_range"; amount: number }> {
  if (amount <= 0 || amount > 1_000_000) {
    return { ok: false, error: { code: "out_of_range", amount } };
  }
  return { ok: true, value: amount };
}

export function toCents(
  amount: number,
): Result<number, { code: "too_precise"; amount: number }> {
  // Comparing against the decimal string avoids the floating-point trap:
  // `1.005 * 100` is 100.49999999999999, which a naive check misreads.
  const fixed = amount.toFixed(2);
  if (Number(fixed) !== amount) {
    return { ok: false, error: { code: "too_precise", amount } };
  }
  return { ok: true, value: Math.round(Number(fixed) * 100) };
}

export type PipelineError =
  | { code: "not_a_number"; text: string }
  | { code: "out_of_range"; amount: number }
  | { code: "too_precise"; amount: number };

export function parseCents(text: string): Result<number, PipelineError> {
