export interface Step<S> {
  readonly name: string;
  readonly run: (state: S) => Result<S, string>;
  readonly undo: (state: S) => S;
}

export interface TxFailure {
  readonly failedAt: string;
  readonly error: string;
  readonly rolledBack: readonly string[];
}

export function runTransaction<S>(
  initial: S,
  steps: readonly Step<S>[],
): Result<S, TxFailure> {
  let state = initial;
  const completed: Step<S>[] = [];

  for (const step of steps) {
    const outcome = step.run(state);
    if (outcome.ok) {
      state = outcome.value;
      completed.push(step);
      continue;
    }

    // Compensate in reverse: each undo sees the state its own step produced.
    const rolledBack: string[] = [];
    for (let index = completed.length - 1; index >= 0; index -= 1) {
      const done = completed[index];
      state = done.undo(state);
      rolledBack.push(done.name);
    }

    return err({ failedAt: step.name, error: outcome.error, rolledBack });
  }

  return ok(state);
}

