  return report as Readonly<Record<keyof S & string, Source>>;
}

// v3tb04_typed_config_env / challenge - reference solution (author only).

export type Env = Readonly<Record<string, string | undefined>>;

export class ConfigError extends Error {
  readonly issues: readonly string[];
  constructor(issues: readonly string[]) {
    super(`invalid configuration:\n${issues.map((issue) => `  - ${issue}`).join("\n")}`);
    this.name = "ConfigError";
    this.issues = issues;
  }
}

export class Redacted<T> {
  readonly #value: T;
  constructor(value: T) {
    this.#value = value;
  }
  reveal(): T {
    return this.#value;
  }
  toString(): string {
    return "[redacted]";
  }
  toJSON(): string {
    return "[redacted]";
  }
}

export type LogLevel = "debug" | "info" | "warn" | "error";
const LEVELS: readonly LogLevel[] = ["debug", "info", "warn", "error"];

export interface DbConfig {
  readonly host: string;
  readonly port: number;
  readonly password: Redacted<string>;
}

export type ServiceConfig =
  | {
      readonly kind: "development";
      readonly port: number;
      readonly db: DbConfig;
      readonly logLevel: LogLevel;
    }
  | {
      readonly kind: "production";
      readonly port: number;
      readonly db: DbConfig;
      readonly logLevel: LogLevel;
      readonly tls: { readonly certPath: string; readonly keyPath: string };
    };

function clean(raw: string | undefined): string | undefined {
  if (raw === undefined) return undefined;
  const trimmed = raw.trim();
  return trimmed.length === 0 ? undefined : trimmed;
}

export function mergeEnv(...layers: readonly Env[]): Env {
  const merged: Record<string, string> = {};
  for (const layer of layers) {
    for (const [key, raw] of Object.entries(layer)) {
      const value = clean(raw);
      // An empty value is silence, so it never overrides a real one.
      if (value !== undefined) merged[key] = value;
    }
  }
  return merged;
}

function requiredString(env: Env, key: string, issues: string[]): string | undefined {
  const value = clean(env[key]);
  if (value === undefined) issues.push(`${key} is required`);
  return value;
}

function intWithDefault(env: Env, key: string, fallback: number, issues: string[]): number {
  const raw = clean(env[key]);
  if (raw === undefined) return fallback;
  if (!/^\d+$/.test(raw)) {
    issues.push(`${key} must be a non-negative integer, got ${JSON.stringify(raw)}`);
    return fallback;
  }
  return Number(raw);
}

function levelWithDefault(env: Env, fallback: LogLevel, issues: string[]): LogLevel {
  const raw = clean(env["LOG_LEVEL"]);
  if (raw === undefined) return fallback;
  const found = LEVELS.find((level) => level === raw);
  if (found === undefined) {
    issues.push(
      `LOG_LEVEL must be one of ${LEVELS.map((l) => JSON.stringify(l)).join(", ")}, ` +
        `got ${JSON.stringify(raw)}`,
    );
    return fallback;
  }
  return found;
}

function deepFreeze<T>(value: T): T {
  const seen = new WeakSet<object>();
  const freeze = (node: unknown): void => {
    if (typeof node !== "object" || node === null || seen.has(node)) return;
    seen.add(node);
    Object.freeze(node);
    for (const child of Object.values(node)) freeze(child);
  };
  freeze(value);
  return value;
}

export function bootstrap(env: Env, fileLayer: Env = {}): ServiceConfig {
  // The process environment wins over the file layer.
  const merged = mergeEnv(fileLayer, env);

  const appEnv = clean(merged["APP_ENV"]);
  if (appEnv !== "development" && appEnv !== "production") {
    throw new ConfigError([
      `APP_ENV must be one of "development", "production", got ${JSON.stringify(appEnv)}`,
    ]);
  }

  const issues: string[] = [];
  const port = intWithDefault(merged, "PORT", appEnv === "production" ? 443 : 3000, issues);
  const dbHost = requiredString(merged, "DB_HOST", issues);
  const dbPort = intWithDefault(merged, "DB_PORT", 5432, issues);
  const dbPassword = requiredString(merged, "DB_PASSWORD", issues);
  const logLevel = levelWithDefault(merged, appEnv === "production" ? "info" : "debug", issues);

  const certPath =
    appEnv === "production" ? requiredString(merged, "TLS_CERT_PATH", issues) : undefined;
  const keyPath =
    appEnv === "production" ? requiredString(merged, "TLS_KEY_PATH", issues) : undefined;

  if (issues.length > 0 || dbHost === undefined || dbPassword === undefined) {
    throw new ConfigError(issues);
  }

  const db: DbConfig = {
    host: dbHost,
    port: dbPort,
    password: new Redacted(dbPassword),
  };

  if (appEnv === "development") {
    return deepFreeze({ kind: "development", port, db, logLevel });
  }

  if (certPath === undefined || keyPath === undefined) {
    throw new ConfigError(issues);
  }
  return deepFreeze({
    kind: "production",
    port,
    db,
    logLevel,
    tls: { certPath, keyPath },
  });
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function scrub(value: unknown): unknown {
  if (value instanceof Redacted) return "[redacted]";
  if (Array.isArray(value)) return value.map((item: unknown) => scrub(item));
  if (isPlainObject(value)) {
    const result: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value)) result[key] = scrub(child);
    return result;
  }
  return value;
}

export function describeBoot(config: ServiceConfig): unknown {
  // A generic walker, so a secret added to the config next year is covered
  // without anyone remembering to update this function.
  return scrub(config);
}

// v3tb04_typed_config_env / review1 - reference solution (author only).

export class ConfigError extends Error {
  readonly issues: readonly string[];
  constructor(issues: readonly string[]) {
    super(`invalid configuration:\n${issues.map((issue) => `  - ${issue}`).join("\n")}`);
    this.name = "ConfigError";
    this.issues = issues;
  }
}

export class Redacted<T> {
  readonly #value: T;
  constructor(value: T) {
    this.#value = value;
  }
  reveal(): T {
    return this.#value;
  }
  toString(): string {
    return "[redacted]";
  }
  toJSON(): string {
    return "[redacted]";
  }
}

function reject(key: string, expectation: string, raw: string): never {
  throw new ConfigError([`${key} must be ${expectation}, got ${JSON.stringify(raw)}`]);
}

export interface Dsn {
  readonly protocol: "postgres" | "postgresql";
  readonly user: string;
  readonly password: Redacted<string>;
  readonly host: string;
  readonly port: number;
  readonly database: string;
  readonly params: Readonly<Record<string, string>>;
}

export function parseDsn(raw: string, key: string): Dsn {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return reject(key, "a connection string", raw);
  }

  const protocol = url.protocol.replace(/:$/, "");
  if (protocol !== "postgres" && protocol !== "postgresql") {
    reject(key, 'a postgres or postgresql connection string', raw);
  }
  if (url.username === "" || url.password === "") {
    reject(key, "a connection string with a username and password", raw);
  }
  const database = url.pathname.replace(/^\//, "");
  if (database === "") {
    reject(key, "a connection string with a database name", raw);
  }

  const params: Record<string, string> = {};
  url.searchParams.forEach((value, name) => {
    params[name] = value;
  });

  return {
    protocol,
    // URL percent-encodes credentials, so a password containing @ or : comes
    // back as %40 or %3A. Decoding is not optional.
    user: decodeURIComponent(url.username),
    password: new Redacted(decodeURIComponent(url.password)),
    host: url.hostname,
    port: url.port === "" ? 5432 : Number(url.port),
    database,
    params,
  };
}

export function asList(raw: string, _key: string): readonly string[] {
  return raw
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
}

export function asFlagSet<const V extends readonly string[]>(
  known: V,
): (raw: string, key: string) => Readonly<Record<V[number], boolean>> {
  const allowed = new Set<string>(known);

  return (raw, key) => {
    const requested = asList(raw, key);
    const unknown = requested.filter((flag) => !allowed.has(flag));
    if (unknown.length > 0) {
      // A silently ignored flag is the worst outcome: the release looks
      // deployed and behaves as though it is not.
      reject(key, `flags from ${known.map((f) => JSON.stringify(f)).join(", ")}`, unknown.join(","));
    }

    const flags = {} as Record<V[number], boolean>;
    for (const flag of known) {
      flags[flag as V[number]] = requested.includes(flag);
    }
    return flags;
  };
}

// v3tb05_builders_fluent_apis / ex1 - reference solution (author only).

export class Query {
  protected readonly parts: string[] = [];

  select(columns: string): this {
    this.parts.push(`SELECT ${columns}`);
    return this;
  }

  from(table: string): this {
    this.parts.push(`FROM ${table}`);
    return this;
  }

  where(clause: string): this {
    this.parts.push(`WHERE ${clause}`);
    return this;
  }

  toSql(): string {
    return this.parts.join(" ");
  }
}

export class PagedQuery extends Query {
  limit(rows: number): this {
    this.parts.push(`LIMIT ${rows}`);
    return this;
  }

  offset(rows: number): this {
    this.parts.push(`OFFSET ${rows}`);
    return this;
  }
}

export function example(): string {
  // Only compiles because `select` and `from` return `this` rather than Query.
  return new PagedQuery().select("*").from("orders").limit(10).offset(20).toSql();
}

// v3tb05_builders_fluent_apis / ex2 - reference solution (author only).

export interface Builder<T extends object> {
  readonly value: Readonly<T>;
  with<K extends string, V>(key: K, value: V): Builder<T & { [P in K]: V }>;
  build(): Readonly<T>;
}

export function builder<T extends object>(initial: T): Builder<T> {
  return {
    value: initial,

    with<K extends string, V>(key: K, value: V): Builder<T & { [P in K]: V }> {
      // The computed key makes the spread's type looser than the target, so
      // this is the builder's one assertion.
      const next = { ...initial, [key]: value } as unknown as T & { [P in K]: V };
      return builder(next);
    },

    build(): Readonly<T> {
      return { ...initial };
    },
  };
}

export function emptyBuilder(): Builder<Record<never, never>> {
  return builder<Record<never, never>>({});
}

