// v3tb05_builders_fluent_apis / ex3 - reference solution (author only).

export type Method = "GET" | "POST" | "PUT" | "DELETE";

export interface RequestSpec {
  readonly url: string;
  readonly method: Method;
  readonly headers: Readonly<Record<string, string>>;
}

export type RequiredPart = "url" | "method";

export interface RequestBuilder<Missing extends RequiredPart> {
  // Phantom. Without a member that mentions `Missing` without recursing,
  // comparing RequestBuilder<"method"> with RequestBuilder<never> recurses
  // through the methods, the cycle resolves as success, and the type state
  // silently enforces nothing.
  readonly __missing?: Missing;
  url(value: string): RequestBuilder<Exclude<Missing, "url">>;
  method(value: Method): RequestBuilder<Exclude<Missing, "method">>;
  header(name: string, value: string): RequestBuilder<Missing>;
  build(this: RequestBuilder<never>): RequestSpec;
}

interface Draft {
  readonly url?: string;
  readonly method?: Method;
  readonly headers: Readonly<Record<string, string>>;
}

function make<Missing extends RequiredPart>(draft: Draft): RequestBuilder<Missing> {
  return {
    url(value: string): RequestBuilder<Exclude<Missing, "url">> {
      return make<Exclude<Missing, "url">>({ ...draft, url: value });
    },

    method(value: Method): RequestBuilder<Exclude<Missing, "method">> {
      return make<Exclude<Missing, "method">>({ ...draft, method: value });
    },

    header(name: string, value: string): RequestBuilder<Missing> {
      return make<Missing>({
        ...draft,
        headers: { ...draft.headers, [name]: value },
      });
    },

    build(this: RequestBuilder<never>): RequestSpec {
      // Types can be defeated by a cast, so the invariant is checked here too.
      if (draft.url === undefined || draft.method === undefined) {
        throw new Error("request is incomplete");
      }
      return { url: draft.url, method: draft.method, headers: { ...draft.headers } };
    },
  };
}

export function request(): RequestBuilder<RequiredPart> {
  return make<RequiredPart>({ headers: {} });
}

// Negative tests: these must not compile, and the file fails to build if they
// ever start to.
// @ts-expect-error - method has not been supplied
request().url("/orders").build();
// @ts-expect-error - neither part has been supplied
request().build();

// v3tb05_builders_fluent_apis / ex4 - reference solution (author only).

export interface ThemeBuilder<T extends object> {
  group<
    const N extends string,
    const G extends Readonly<Record<string, string | number>>,
  >(
    name: N,
    tokens: G,
  ): ThemeBuilder<T & { readonly [P in N]: G }>;

  scale<const N extends string, const S extends readonly number[]>(
    name: N,
    values: S,
  ): ThemeBuilder<T & { readonly [P in N]: S }>;

  build(): Readonly<T>;
}

function makeTheme<T extends object>(current: T): ThemeBuilder<T> {
  return {
    group<
      const N extends string,
      const G extends Readonly<Record<string, string | number>>,
    >(name: N, tokens: G): ThemeBuilder<T & { readonly [P in N]: G }> {
      const next = { ...current, [name]: tokens } as unknown as T & {
        readonly [P in N]: G;
      };
      return makeTheme(next);
    },

    scale<const N extends string, const S extends readonly number[]>(
      name: N,
      values: S,
    ): ThemeBuilder<T & { readonly [P in N]: S }> {
      const next = { ...current, [name]: values } as unknown as T & {
        readonly [P in N]: S;
      };
      return makeTheme(next);
    },

    build(): Readonly<T> {
      return { ...current };
    },
  };
}

export function theme(): ThemeBuilder<Record<never, never>> {
  return makeTheme<Record<never, never>>({});
}

