// v3tb05_builders_fluent_apis / ex5 - reference solution (author only).

export interface Field<T extends string> {
  readonly options: readonly T[];
  readonly fallback: T;
  parse(raw: string): T;
}

export interface FieldBuilder<T extends string> {
  fallback(value: NoInfer<T>): FieldBuilder<T>;
  alias(from: string, to: NoInfer<T>): FieldBuilder<T>;
  build(): Field<T>;
}

function makeField<T extends string>(
  options: readonly T[],
  fallback: T | undefined,
  aliases: Readonly<Record<string, T>>,
): FieldBuilder<T> {
  return {
    fallback(value: T): FieldBuilder<T> {
      return makeField(options, value, aliases);
    },

    alias(from: string, to: T): FieldBuilder<T> {
      return makeField(options, fallback, { ...aliases, [from]: to });
    },

    build(): Field<T> {
      if (fallback === undefined) {
        throw new Error("field has no fallback");
      }
      const resolved = fallback;
      const allowed = new Set<string>(options);
      return {
        options,
        fallback: resolved,
        parse(raw: string): T {
          const mapped: string = aliases[raw] ?? raw;
          return allowed.has(mapped) ? (mapped as T) : resolved;
        },
      };
    },
  };
}

export function field<const V extends readonly string[]>(
  options: V,
): FieldBuilder<V[number]> {
  return makeField<V[number]>(options, undefined, {});
}

// Negative tests. Delete a NoInfer and one of these starts compiling, with T
// silently gaining a third member.
// @ts-expect-error - "purple" is not one of the declared options
field(["light", "dark"]).fallback("purple");
// @ts-expect-error - an alias must point at a declared option
field(["light", "dark"]).alias("x", "purple");

// v3tb05_builders_fluent_apis / ex6 - reference solution (author only).

export type OnceOnly = "select" | "limit";

interface QueryMethods<Used extends OnceOnly> {
  select(columns: string): Query<Used | "select">;
  where(clause: string): Query<Used>;
  limit(rows: number): Query<Used | "limit">;
  sql(): string;
}

// The methods live on an interface so this alias does not reference itself
// through a mapped type, which TypeScript rejects as circular.
export type Query<Used extends OnceOnly = never> = Omit<QueryMethods<Used>, Used>;

interface State {
  readonly table: string;
  readonly columns: string;
  readonly wheres: readonly string[];
  readonly limit: number | undefined;
}

function make<Used extends OnceOnly>(state: State): Query<Used> {
  const methods: QueryMethods<Used> = {
    select(columns: string): Query<Used | "select"> {
      return make<Used | "select">({ ...state, columns });
    },

    where(clause: string): Query<Used> {
      return make<Used>({ ...state, wheres: [...state.wheres, clause] });
    },

    limit(rows: number): Query<Used | "limit"> {
      return make<Used | "limit">({ ...state, limit: rows });
    },

    sql(): string {
      const parts = [`SELECT ${state.columns}`, `FROM ${state.table}`];
      if (state.wheres.length > 0) {
        parts.push(`WHERE ${state.wheres.join(" AND ")}`);
      }
      if (state.limit !== undefined) {
        parts.push(`LIMIT ${state.limit}`);
      }
      return parts.join(" ");
    },
  };

  return methods;
}

export function query(table: string): Query {
  return make<never>({ table, columns: "*", wheres: [], limit: undefined });
}

// Negative tests: the methods are genuinely gone, so the error is a missing
// property rather than a type mismatch.
// @ts-expect-error - select may only be called once
query("orders").select("id").select("name");
// @ts-expect-error - limit may only be called once
query("orders").limit(1).limit(2);

// v3tb05_builders_fluent_apis / ex7 - reference solution (author only).

export type Mode = "one" | "many";

export function pick<Row>(rows: readonly Row[], mode: "one"): Row | undefined;
export function pick<Row>(rows: readonly Row[], mode: "many"): Row[];
export function pick<Row>(
  rows: readonly Row[],
  mode: Mode,
): Row | undefined | Row[] {
  return mode === "one" ? rows[0] : [...rows];
}

export type PickResult<Row, M extends Mode> = M extends "one"
  ? Row | undefined
  : Row[];

export function pickConditional<Row, M extends Mode>(
  rows: readonly Row[],
  mode: M,
): PickResult<Row, M> {
  // The compiler cannot relate a runtime branch to a type-level conditional,
  // so this assertion is the approach's unavoidable cost.
  return (mode === "one" ? rows[0] : [...rows]) as PickResult<Row, M>;
}

// Observed in an editor:
//
// 1. Tooltips. Hovering `pick(rows, "one")` shows `number | undefined`.
//    Hovering `pickConditional(rows, "one")` shows
//    `PickResult<number, "one">` - accurate, and no help to a reader.
//
// 2. Errors. `pick(rows, "some")` reports "No overload matches this call",
//    then lists both signatures with the accepted literals. The conditional
//    version reports that `"some"` is not assignable to `Mode`, which is
//    shorter but does not show the caller what the alternatives were.
//
// Ship the overloads for a public API of a few named cases; keep the
// conditional when the function must be wrapped by other generic code, since
// overloads do not survive `Parameters`/`ReturnType`.

