// v3tb05_builders_fluent_apis / ex8 - reference solution (author only).

export type Part = "from" | "select";

interface Methods<Missing extends Part> {
  readonly __missing?: Missing;
  from(table: string): Builder<Exclude<Missing, "from">>;
  select(columns: readonly string[]): Builder<Exclude<Missing, "select">>;
  where(clause: string): Builder<Missing>;
  build(this: Builder<never>): string;
}

export type Removed<Missing extends Part> =
  // no FROM yet, so WHERE is not offered
  | ("from" extends Missing ? "where" : never)
  // FROM supplied, so it cannot be supplied again
  | ("from" extends Missing ? never : "from")
  // SELECT supplied, so it cannot be supplied again
  | ("select" extends Missing ? never : "select");

export type Builder<Missing extends Part> = Omit<Methods<Missing>, Removed<Missing>>;

interface State {
  readonly table: string | undefined;
  readonly columns: readonly string[] | undefined;
  readonly wheres: readonly string[];
}

function make<Missing extends Part>(state: State): Builder<Missing> {
  const methods: Methods<Missing> = {
    from(table: string): Builder<Exclude<Missing, "from">> {
      return make<Exclude<Missing, "from">>({ ...state, table });
    },

    select(columns: readonly string[]): Builder<Exclude<Missing, "select">> {
      return make<Exclude<Missing, "select">>({ ...state, columns: [...columns] });
    },

    where(clause: string): Builder<Missing> {
      return make<Missing>({ ...state, wheres: [...state.wheres, clause] });
    },

    build(this: Builder<never>): string {
      if (state.table === undefined || state.columns === undefined) {
        throw new Error("query is incomplete");
      }
      const parts = [`SELECT ${state.columns.join(", ")}`, `FROM ${state.table}`];
      if (state.wheres.length > 0) {
        parts.push(`WHERE ${state.wheres.join(" AND ")}`);
      }
      return parts.join(" ");
    },
  };

  return methods;
}

export function sql(): Builder<Part> {
  return make<Part>({ table: undefined, columns: undefined, wheres: [] });
}

// Negative tests: the grammar, stated as four things that must not compile.
// @ts-expect-error - where is not offered before from
sql().where("a");
// @ts-expect-error - from may only be called once
sql().from("t").from("u");
// @ts-expect-error - select may only be called once
sql().from("t").select(["a"]).select(["b"]);
// @ts-expect-error - select has not been supplied
sql().from("t").build();

