```

references.solution.ts:
// v3tb05_builders_fluent_apis / challenge - reference solution (author only).

export type Method = "GET" | "POST" | "PUT" | "DELETE";

export interface RequestSpec {
  readonly url: string;
  readonly method: Method;
  readonly headers: Readonly<Record<string, string>>;
  readonly query: Readonly<Record<string, string>>;
}

export type MissingPart = "url" | "decoder";

export interface Client<Missing extends MissingPart, Body> {
  readonly __missing?: Missing;
  url(value: string): Client<Exclude<Missing, "url">, Body>;
  method(value: Method): Client<Missing, Body>;
  header(name: string, value: string): Client<Missing, Body>;
  query<const Q extends Readonly<Record<string, string | number | boolean>>>(
    params: Q,
  ): Client<Missing, Body>;
  expect<T>(decode: (value: unknown) => T): Client<Exclude<Missing, "decoder">, T>;
  send(
    this: Client<never, Body>,
    transport: (spec: RequestSpec) => Promise<unknown>,
  ): Promise<Body>;
}

interface Draft {
  readonly url: string | undefined;
  readonly method: Method;
  readonly headers: Readonly<Record<string, string>>;
  readonly query: Readonly<Record<string, string>>;
  readonly decode: ((value: unknown) => unknown) | undefined;
}

function make<Missing extends MissingPart, Body>(draft: Draft): Client<Missing, Body> {
  return {
    url(value: string): Client<Exclude<Missing, "url">, Body> {
      return make<Exclude<Missing, "url">, Body>({ ...draft, url: value });
    },

    method(value: Method): Client<Missing, Body> {
      return make<Missing, Body>({ ...draft, method: value });
    },

    header(name: string, value: string): Client<Missing, Body> {
      return make<Missing, Body>({
        ...draft,
        headers: { ...draft.headers, [name]: value },
      });
    },

    query<const Q extends Readonly<Record<string, string | number | boolean>>>(
      params: Q,
    ): Client<Missing, Body> {
      const merged: Record<string, string> = { ...draft.query };
      for (const [key, value] of Object.entries(params)) {
        merged[key] = String(value);
      }
      return make<Missing, Body>({ ...draft, query: merged });
    },

    expect<T>(decode: (value: unknown) => T): Client<Exclude<Missing, "decoder">, T> {
      return make<Exclude<Missing, "decoder">, T>({ ...draft, decode });
    },

    async send(
      this: Client<never, Body>,
      transport: (spec: RequestSpec) => Promise<unknown>,
    ): Promise<Body> {
      const decode = draft.decode;
      if (draft.url === undefined || decode === undefined) {
        throw new Error("request is incomplete");
      }
      const spec: RequestSpec = {
        url: draft.url,
        method: draft.method,
        headers: { ...draft.headers },
        query: { ...draft.query },
      };
      const raw = await transport(spec);
      // One assertion: the stored decoder is erased to (unknown) => unknown,
      // and `Body` is the type the chain recorded when `expect` was called.
      return decode(raw) as Body;
    },
  };
}

export function client(): Client<MissingPart, never> {
  return make<MissingPart, never>({
    url: undefined,
    method: "GET",
    headers: {},
    query: {},
    decode: undefined,
  });
}

const transport = async (_spec: RequestSpec): Promise<unknown> => ({});
const decodeAnything = (value: unknown): { ok: boolean } => ({ ok: value !== null });

// Negative tests: the three incomplete states.
// @ts-expect-error - no decoder has been supplied
void client().url("/x").send(transport);
// @ts-expect-error - no url has been supplied
void client().expect(decodeAnything).send(transport);
// @ts-expect-error - neither has been supplied
void client().send(transport);

