## Review — a form whose parsed type is built by the chain

Edit `review1/solution.ts`. Same machinery, different domain: fields declared
one at a time, and a parsed value whose type is the sum of them.

```ts
export type FormResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly errors: Readonly<Record<string, string>> };

export interface Form<T extends object> {
  readonly names: readonly string[];
  parse(input: Readonly<Record<string, string>>): FormResult<T>;
}

export interface FormBuilder<T extends object> {
  field<const N extends string, V>(
    name: N,
    parse: (raw: string, name: string) => V,
  ): FormBuilder<T & { readonly [P in N]: V }>;
  optionalField<const N extends string, V>(
    name: N,
    parse: (raw: string, name: string) => V,
  ): FormBuilder<T & { readonly [P in N]?: V }>;
  build(): Form<T>;
}

export function form(): FormBuilder<Record<never, never>>
```

With

```ts
const signup = form()
  .field("email", (raw, name) => { if (!raw.includes("@")) throw new Error(`${name} must be an email`); return raw; })
  .field("age", (raw, name) => { const n = Number(raw); if (!Number.isInteger(n)) throw new Error(`${name} must be a whole number`); return n; })
  .optionalField("referrer", (raw) => raw)
  .build();
```

- `signup.names` → `["email", "age", "referrer"]`, in declaration order
- `signup.parse({ email: "a@b", age: "41" })` →
  `{ ok: true, value: { email: "a@b", age: 41 } }`, and the value's type is
  `{ readonly email: string; readonly age: number; readonly referrer?: string }`
- The `referrer` key is **absent** from the parsed value when not supplied, not
  present-and-undefined
- `signup.parse({ email: "nope", age: "x" })` →
  `{ ok: false, errors: { email: "email must be an email", age: "age must be a whole number" } }`
  — every field is attempted, not just the first
- A missing required field reports `"email is required"`
- An empty string counts as missing
- `signup.parse({}).ok` is `false` with two errors

