// v3tb05_builders_fluent_apis / review1 - reference solution (author only).

export type FormResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly errors: Readonly<Record<string, string>> };

export interface Form<T extends object> {
  readonly names: readonly string[];
  parse(input: Readonly<Record<string, string>>): FormResult<T>;
}

export interface FormBuilder<T extends object> {
  field<const N extends string, V>(
    name: N,
    parse: (raw: string, name: string) => V,
  ): FormBuilder<T & { readonly [P in N]: V }>;
  optionalField<const N extends string, V>(
    name: N,
    parse: (raw: string, name: string) => V,
  ): FormBuilder<T & { readonly [P in N]?: V }>;
  build(): Form<T>;
}

interface FieldSpec {
  readonly name: string;
  readonly parse: (raw: string, name: string) => unknown;
  readonly optional: boolean;
}

function makeForm<T extends object>(fields: readonly FieldSpec[]): FormBuilder<T> {
  return {
    field<const N extends string, V>(
      name: N,
      parse: (raw: string, name: string) => V,
    ): FormBuilder<T & { readonly [P in N]: V }> {
      return makeForm<T & { readonly [P in N]: V }>([
        ...fields,
        { name, parse, optional: false },
      ]);
    },

    optionalField<const N extends string, V>(
      name: N,
      parse: (raw: string, name: string) => V,
    ): FormBuilder<T & { readonly [P in N]?: V }> {
      return makeForm<T & { readonly [P in N]?: V }>([
        ...fields,
        { name, parse, optional: true },
      ]);
    },

    build(): Form<T> {
      const declared = fields.map((field) => field.name);
      return {
        names: declared,
        parse(input: Readonly<Record<string, string>>): FormResult<T> {
          const value: Record<string, unknown> = {};
          const errors: Record<string, string> = {};

          for (const field of fields) {
            const raw = input[field.name];
            const present = raw !== undefined && raw.length > 0;

            if (!present) {
              if (!field.optional) {
                errors[field.name] = `${field.name} is required`;
              }
              // Optional and absent: the key stays absent, not undefined.
              continue;
            }

            try {
              value[field.name] = field.parse(raw, field.name);
            } catch (thrown) {
              errors[field.name] =
                thrown instanceof Error ? thrown.message : String(thrown);
            }
          }

          if (Object.keys(errors).length > 0) {
            return { ok: false, errors };
          }
          return { ok: true, value: value as unknown as T };
        },
      };
    },
  };
}

export function form(): FormBuilder<Record<never, never>> {
  return makeForm<Record<never, never>>([]);
}
